def fill_labels(apps, schema_editor):
    """Existing history lines get the name of their record, so they stay meaningful if it is ever deleted for good."""
    Log, Policy = apps.get_model("tickets", "InsuranceLog"), apps.get_model("tickets", "InsurancePolicy")
    for p in Policy.objects.select_related("cover_type").prefetch_related("centres"):
        where = ", ".join(sorted(c.name for c in p.centres.all())) or "All centres"
        Log.objects.filter(policy=p, label="").update(label=f"{p.cover_type.name}, {where}, {p.insurer} {p.policy_number}"[:250])
    LLog, Lic = apps.get_model("tickets", "LicenceLog"), apps.get_model("tickets", "Licence")
    for x in Lic.objects.prefetch_related("centres"):
        where = ", ".join(sorted(c.name for c in x.centres.all())) or "All centres"
        LLog.objects.filter(licence=x, label="").update(label=f"{x.name}, {where}{', ' + x.reference_number if x.reference_number else ''}"[:250])


